node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { createRepository } from './src/repository.mjs';
import { collectAll } from './src/collect.mjs';

const repo = createRepository([
  { id: 1 },
  { id: 2, deleted: true },
  { id: 3, deleted: true },
  { id: 4 },
  { id: 5 }
]);
assert.deepEqual(await repo.page({ cursor: null, limit: 2 }), {
  items: [{ id: 1 }], nextCursor: 2
});
assert.deepEqual(await repo.page({ cursor: 2, limit: 2 }), {
  items: [], nextCursor: 4
});
assert.deepEqual(await collectAll(repo, { limit: 2 }), [
  { id: 1 }, { id: 4 }, { id: 5 }
]);
await assert.rejects(
  collectAll({ page: async () => ({ items: [], nextCursor: 7 }) }, { maxPages: 4 }),
  /Repeated cursor/
);
let calls = 0;
await assert.rejects(
  collectAll({ page: async () => ({ items: [], nextCursor: ++calls }) }, { maxPages: 2 }),
  /Page budget exhausted/
);
assert.equal(calls, 2);
console.log('Contract checks passed');
